{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f6efe6;--card:#fff7ef;--accent:#8b5e3c;--muted:#6b5848;--glass:rgba(255,255,255,0.6)}
    html,body{height:100%;margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;
      color:var(--muted);background:linear-gradient(180deg,var(--bg),#fff);}
    header{display:flex;align-items:center;justify-content:space-between;padding:20px 28px;background:transparent}
    .brand{display:flex;gap:14px;align-items:center}
    .logo{width:56px;height:56px;border-radius:10px;background:linear-gradient(135deg,#f9efe0,#efe1d0);box-shadow:0 6px 18px rgba(139,94,60,0.12);display:grid;place-items:center;font-weight:700;color:var(--accent)}
    nav a{color:var(--muted);text-decoration:none;margin-left:18px;font-weight:600}
    main{max-width:1000px;margin:28px auto;padding:26px}
    .hero{display:grid;grid-template-columns:1fr 360px;gap:26px;align-items:start}
    .card{background:var(--card);padding:22px;border-radius:14px;box-shadow:0 8px 30px rgba(99,67,45,0.06)}
    h1{margin:0 0 8px;font-size:28px;color:var(--accent)}
    p.lead{margin:0 0 16px;color:#5b4839}
    .meta{font-size:14px;color:#7a6a5a}
    .divider{height:1px;background:linear-gradient(90deg,transparent,#e9dcd0,transparent);margin:18px 0}
    .features{display:flex;flex-direction:column;gap:12px}
    .feature{display:flex;gap:12px;align-items:flex-start}
    .icon{width:44px;height:44px;border-radius:10px;background:linear-gradient(180deg,#fff,#f5ebe1);display:grid;place-items:center;color:var(--accent);font-weight:700}
    footer.cta{margin-top:20px;padding:18px;border-radius:12px;background:linear-gradient(180deg,rgba(139,94,60,0.06),transparent)}

    /* pattern: an earthy tile rendered as inline svg and usable as img */
    .pattern-wrap{position:fixed;right:20px;bottom:20px;width:220px;height:220px;opacity:0.12;pointer-events:none}
    /* Mini interactive widget */
    .mini-planner{background:linear-gradient(180deg,#fff,#fff7f2);padding:16px;border-radius:10px}
    .mini-planner label{display:block;font-size:13px;margin-top:8px;color:#634734}
    .mini-planner input,.mini-planner select{width:100%;padding:8px;border-radius:8px;border:1px solid #e6ddd2;background:transparent}
    .btn{display:inline-block;padding:10px 14px;border-radius:10px;background:var(--accent);color:#fff;text-decoration:none;border:none;cursor:pointer}
    .muted-block{font-size:13px;color:#6b5848}
    pre.export{white-space:pre-wrap;background:#fff7ef;padding:12px;border-radius:8px;border:1px solid #f0e3d7;margin-top:12px}
    small.disclaimer{display:block;margin-top:12px;color:#6b5144;font-size:12px}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">SB</div>
      <div>
        <div style="font-weight:700;color:var(--accent)">{{BUSINESS_NAME}}</div>
        <div style="font-size:13px;color:#7a6a5a">{{TAGLINE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="events.html">Gatherings</a>
      <a href="private-sessions.html">Quiet Rooms</a>
      <a href="pricing.html">Investment</a>
      <a href="about.html">Story</a>
      <a href="faq.html">Q&A</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Hello</a>
    </nav>
  </header>

  <main>
    <div class="hero">
      <section class="card">
        <h1>Who we are and how we work with sound</h1>
        <p class="lead">We host slow, warm gatherings that use tuned instruments and gentle rhythm to create a soft container: attentive, relaxed, and open to small changes. Our practice is about shaping space for rest and clarity, not performance.</p>
        <div class="divider"></div>
        <div class="features">
          <div class="feature"><div class="icon">G</div><div><strong>Grounded curation</strong><div class="muted-block">We blend bowls, subtle percussion and breath-led guidance to make a steady arc across the session.</div></div></div>
          <div class="feature"><div class="icon">H</div><div><strong>Warm hospitality</strong><div class="muted-block">Small events, clear entry and exit, and guidance for what to bring so your experience is smooth.</div></div></div>
          <div class="feature"><div class="icon">P</div><div><strong>Practical accessibility</strong><div class="muted-block">Quiet arrival, accessible seating options, and a considerate environment for diverse needs.</div></div></div>
        </div>
        <footer class="cta">
          <div style="display:flex;justify-content:space-between;align-items:center">
            <div>
              <div style="font-weight:700;color:var(--accent)">Curious to join?</div>
              <div style="font-size:13px;color:#6b5848">Plan a personal session below or head to Reserve to pick a gathering.</div>
            </div>
            <div>
              <a class="btn" href="book.html">Plan with us</a>
            </div>
          </div>
        </footer>
      </section>

      <aside class="card">
        <h3 style="margin-top:0;color:var(--accent)">Session Planner (quick)</h3>
        <div class="mini-planner" id="miniPlanner">
          <label for="name">Your name</label>
          <input id="name" placeholder="Maria" />
          <label for="intent">What would you like to place attention on?</label>
          <select id="intent"><option>Rest & reset</option><option>Sleep preparation</option><option>Creative focus</option><option>Transition & ritual</option></select>
          <label for="length">Duration</label>
          <select id="length"><option>30 minutes</option><option>45 minutes</option><option>60 minutes</option></select>
          <button class="btn" id="miniBuild" style="margin-top:12px">Compose plan</button>
          <pre class="export" id="miniExport" aria-live="polite">Your plan will appear here.</pre>
          <div style="display:flex;gap:8px;margin-top:8px">
            <button class="btn" id="miniCopy">Copy</button>
            <button style="background:#fff;border:1px solid #e6ddd2;padding:10px;border-radius:10px;cursor:pointer" id="miniOpen">Open full planner</button>
          </div>
          <small class="disclaimer">Health note: If you have a history of seizures, inner-ear conditions, or severe psychiatric episodes, consult a clinician before attending sound sessions.</small>
        </div>
      </aside>
    </div>

    <section style="margin-top:22px" class="card">
      <h3 style="color:var(--accent);margin-top:0">Our approach — a brief process</h3>
      <ol style="color:#6b5848">
        <li><strong>Arrival & settling:</strong> Quiet check-in, choice of cushion or chair, 5–10 minutes of guided grounding.</li>
        <li><strong>Sound arc:</strong> Instruments layered in a slow build and gentle resolution.</li>
        <li><strong>Soft close:</strong> A brief recalibration and space for water and questions.</li>
      </ol>
      <div class="divider"></div>
      <p style="color:#6b5848">We welcome questions about accessibility and welcome small changes to support everyone’s comfort. If uncertain, reach out: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> or call <a href="tel:{{PHONE}}">{{PHONE}}</a>.</p>
    </section>

  </main>

  <div class="pattern-wrap" aria-hidden="true">
    <!-- Inline decorative svg pattern: warm earthen tiles -->
    <svg width="220" height="220" viewBox="0 0 220 220" xmlns="http://www.w3.org/2000/svg">
      <defs>
        <pattern id="tile" width="44" height="44" patternUnits="userSpaceOnUse">
          <rect width="44" height="44" fill="#efe1d0" />
          <circle cx="22" cy="22" r="6" fill="#f9efe0" />
          <path d="M2 22 Q22 6 42 22" stroke="#e0c7b0" stroke-width="1.5" fill="none"/>
        </pattern>
      </defs>
      <rect width="220" height="220" fill="url(#tile)" opacity="0.9"/>
    </svg>
  </div>

  <script>
    // Mini planner logic
    (function(){
      const buildBtn = document.getElementById('miniBuild');
      const copyBtn = document.getElementById('miniCopy');
      const openBtn = document.getElementById('miniOpen');
      const exportArea = document.getElementById('miniExport');
      function compose(){
        const name = document.getElementById('name').value || 'Friend';
        const intent = document.getElementById('intent').value;
        const length = document.getElementById('length').value;
        const plan = [
          `Session plan for: ${name}`,
          `Focus: ${intent}`,
          `Length: ${length}`,
          `Structure:`,
          ` • 5–10 min arrival & breath-led settling`,
          ` • 50–70% of time in layered harmonic bowls and soft percussion`,
          ` • slow resolution & 3-minute silence to finish`,
          `Notes: Bring a cushion and a light blanket. Avoid heavy meals before arrival.`
        ].join('\n');
        exportArea.textContent = plan;
      }
      buildBtn.addEventListener('click',compose);
      copyBtn.addEventListener('click',function(){
        navigator.clipboard && navigator.clipboard.writeText(exportArea.textContent).then(()=>{
          copyBtn.textContent='Copied'
          setTimeout(()=>copyBtn.textContent='Copy',1200)
        })
      });
      openBtn.addEventListener('click',function(){ location.href='book.html' });
    })();
  </script>
</body>
</html>"} 
{"path":"faq.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>FAQ — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbf6f1;--accent:#7a4f36;--muted:#6b5848}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;background:var(--bg);color:var(--muted)}
    header{padding:18px 26px;display:flex;justify-content:space-between;align-items:center}
    header .logo{font-weight:800;color:var(--accent)}
    nav a{margin-left:16px;color:var(--muted);text-decoration:none;font-weight:600}
    main{max-width:940px;margin:14px auto;padding:18px}
    .top{display:flex;gap:18px;align-items:center}
    h1{margin:0;color:var(--accent)}
    .grid{display:grid;grid-template-columns:1fr 320px;gap:18px;margin-top:18px}

    .faq-card{background:white;padding:18px;border-radius:12px;box-shadow:0 8px 22px rgba(94,63,41,0.06)}
    details summary{cursor:pointer;font-weight:700;color:#5b4334;padding:8px 0}
    details p{margin:6px 0 12px;color:#6b5848}
    .side{position:sticky;top:20px}
    .btn{display:inline-block;padding:10px 12px;border-radius:10px;background:var(--accent);color:#fff;text-decoration:none}
    .small{font-size:13px;color:#6b5848}
    .packing{background:#fff7ef;padding:12px;margin-top:12px;border-radius:10px}
    .seat-map{display:grid;grid-template-columns:repeat(5,36px);gap:8px;justify-content:center;margin-top:12px}
    .seat{width:36px;height:36px;background:#fff;border-radius:6px;border:1px solid #e6ddd2;display:grid;place-items:center;cursor:pointer}
    .seat.selected{background:#8b5e3c;color:#fff}
    small.warn{display:block;color:#7a4836;margin-top:10px}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;align-items:center;gap:12px"><div class="logo">{{BUSINESS_NAME}}</div><div class="small">Answers + helpful notes</div></div>
    <nav>
      <a href="index.html">Home</a>
      <a href="events.html">Gatherings</a>
      <a href="book.html">Reserve</a>
    </nav>
  </header>

  <main>
    <div class="top">
      <div>
        <h1>Questions we hear often</h1>
        <p class="small">Practical answers and a few suggestions to prepare for a sound gathering with us.</p>
      </div>
      <div style="margin-left:auto;align-self:center"><a class="btn" href="book.html">Reserve a spot</a></div>
    </div>

    <div class="grid">
      <section class="faq-card">
        <details open>
          <summary>What should I bring?</summary>
          <p>Comfortable clothing, a cushion or yoga mat, a light blanket, and water. If you have a preferred pillow or neck support bring it along.</p>
        </details>
        <details>
          <summary>How long are the sessions?</summary>
          <p>Typical gatherings are 45–60 minutes. We also offer 30-minute options for those who prefer a shorter arrival.</p>
        </details>
        <details>
          <summary>Are sessions suitable for beginners?</summary>
          <p>Yes. We welcome anyone. The environment is non-judgmental and the invitation is to notice how sound interacts with your attention.</p>
        </details>
        <details>
          <summary>Contraindications and safety</summary>
          <p>If you are pregnant, have a diagnosis of epilepsy, are recovering from a recent head injury, or have inner-ear conditions, please consult your physician before attending. Our sessions are not a substitute for medical care.</p>
        </details>
        <details>
          <summary>Can I talk to the facilitator beforehand?</summary>
          <p>Yes — email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> or call <a href="tel:{{PHONE}}">{{PHONE}}</a> to discuss accommodations.</p>
        </details>

        <div style="margin-top:12px">
          <strong>More resources</strong>
          <p class="small">If you'd like a tailored packing list, test our seat selector on the right to see suggested items based on your seat and preferences.</p>
        </div>
      </section>

      <aside class="side">
        <div class="faq-card">
          <h3 style="margin-top:0;color:var(--accent)">Seat test & packing suggestions</h3>
          <div class="small">Click to pick a seat (this is a simulated selector to help plan).</div>
          <div class="seat-map" id="seatMap" aria-hidden="false"></div>
          <div class="packing" id="packing">
            <strong>What to bring</strong>
            <ul id="packList">
              <li>Blanket</li>
              <li>Cushion or mat</li>
              <li>Water bottle</li>
            </ul>
          </div>
          <small class="warn">Note: This tool is only a planner; actual seat assignments are done at check-in.</small>
        </div>
      </aside>
    </div>

  </main>

  <script>
    // Fake seat selector that updates packing list
    (function(){
      const seatMap = document.getElementById('seatMap');
      const packList = document.getElementById('packList');
      const totalSeats = 20; // 4 rows of 5
      for(let i=1;i<=totalSeats;i++){
        const s = document.createElement('div');
        s.className='seat';
        s.textContent=i;
        s.dataset.id = i;
        s.addEventListener('click',()=>{
          document.querySelectorAll('.seat').forEach(x=>x.classList.remove('selected'));
          s.classList.add('selected');
          updatePacking(i);
        });
        seatMap.appendChild(s);
      }
      function updatePacking(n){
        const list = ['Blanket','Cushion or mat','Water bottle'];
        // seats near front -> suggest earplugs; back -> extra cushion
        if(n<=5) list.push('Light earplugs (optional)');
        if(n>15) list.push('Extra lumbar support or folded blanket');
        if(n%2===0) list.push('Small towel');
        packList.innerHTML = list.map(it=>`<li>${it}</li>`).join('');
      }
      // preselect a seat
      document.querySelectorAll('.seat')[7].click();
    })();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Reserve — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f8f2ec;--accent:#8b5e3c;--muted:#5d4639}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;background:var(--bg);color:var(--muted)}
    header{display:flex;justify-content:space-between;padding:18px 26px;align-items:center}
    nav a{margin-left:14px;color:var(--muted);text-decoration:none}
    main{max-width:1120px;margin:18px auto;padding:14px}
    .grid{display:grid;grid-template-columns:1fr 420px;gap:18px}
    .panel{background:#fff;padding:18px;border-radius:12px;box-shadow:0 10px 26px rgba(95,63,38,0.06)}
    h1{margin:0;color:var(--accent)}
    form label{display:block;margin-top:12px;font-weight:700;color:#6b5040}
    input,select,textarea{width:100%;padding:10px;border-radius:8px;border:1px solid #efe4d8;margin-top:6px}
    .btn{background:var(--accent);color:#fff;padding:10px 14px;border-radius:10px;border:none;cursor:pointer}
    .seat-grid{display:grid;grid-template-columns:repeat(5,52px);gap:8px;justify-content:center;margin-top:12px}
    .seat{width:52px;height:52px;border-radius:8px;background:#fff;border:1px solid #efe4d8;display:grid;place-items:center;cursor:pointer}
    .seat.selected{background:var(--accent);color:#fff}
    .summary{white-space:pre-wrap;background:#fff7ef;padding:12px;border-radius:8px;margin-top:12px;border:1px solid #f0e3d7}
    .disclaimer{font-size:13px;color:#6b5040;margin-top:10px}
  </style>
</head>
<body>
  <header>
    <div style="font-weight:800;color:var(--accent)">{{BUSINESS_NAME}}</div>
    <nav>
      <a href="index.html">Home</a>
      <a href="events.html">Gatherings</a>
      <a href="about.html">Story</a>
      <a href="contact.html">Hello</a>
    </nav>
  </header>

  <main>
    <div class="grid">
      <section class="panel">
        <h1>Reserve a gathering or private session</h1>
        <p style="color:#6b5040">Choose a public event or request a private appointment. Use the planner to shape a personal experience and then copy the summary into our booking form.</p>

        <form id="bookingForm" onsubmit="return false;">
          <label for="type">Choose</label>
          <select id="type">
            <option value="public">Public gathering — community seating</option>
            <option value="private">Private session — tailored</option>
            <option value="short">Brief practice — 30 min</option>
          </select>

          <label for="date">Preferred date</label>
          <input id="date" type="date" />

          <label for="name">Your name</label>
          <input id="custName" placeholder="Your full name" />

          <label for="email">Email</label>
          <input id="custEmail" placeholder="you@example.com" />

          <label for="notes">Notes / accessibility needs</label>
          <textarea id="notes" rows="3" placeholder="Anything we should know"></textarea>

          <div style="display:flex;gap:10px;margin-top:12px;align-items:center">
            <button class="btn" id="submitBtn">Request booking</button>
            <button type="button" id="previewBtn" style="background:#fff;border:1px solid #e6ddd2;padding:10px;border-radius:10px;cursor:pointer">Preview summary</button>
          </div>

          <div class="disclaimer">If you are pregnant, have epilepsy, recent head injury, or inner ear disorders, consult a clinician before attending. Not a replacement for medical care.</div>
        </form>

        <div id="result" class="summary" aria-live="polite">Build a plan and preview it here.</div>
      </section>

      <aside>
        <div class="panel">
          <h3 style="margin-top:0;color:var(--accent)">Session Planner</h3>
          <div class="small">Craft a personalized outline. Copy into the booking form or share the plaintext.</div>

          <label for="p-intent">Intention</label>
          <select id="p-intent"><option>Rest & unwinding</option><option>Sleep preparation</option><option>Focus & clarity</option><option>Transition ritual</option><option>Grief & release</option></select>

          <label for="p-duration">Duration</label>
          <select id="p-duration"><option value="30">30 minutes</option><option value="45" selected>45 minutes</option><option value="60">60 minutes</option></select>

          <label for="p-tone">Sound texture</label>
          <select id="p-tone"><option>Harmonic bowls</option><option>Light percussion</option><option>Drone & breath</option><option>Mixed gentle</option></select>

          <label for="p-env">Ambience</label>
          <select id="p-env"><option>Quiet</option><option>Soft guided voice</option><option>Minimal verbal prompts</option></select>

          <div style="display:flex;gap:8px;margin-top:12px">
            <button class="btn" id="buildPlan">Compose</button>
            <button id="copyPlan" style="background:#fff;border:1px solid #e6ddd2;padding:10px;border-radius:10px;cursor:pointer">Copy</button>
          </div>

          <pre id="planOut" class="summary">Your custom plan will appear here.</pre>

          <div style="margin-top:10px">
            <strong>Seat selector</strong>
            <div class="seat-grid" id="seatGrid"></div>
            <div style="margin-top:10px" class="small">Pick a seat to see a suggested packing list for that location.</div>
            <div id="packingBox" class="summary">Suggested items will appear here.</div>
          </div>
        </div>

        <div style="margin-top:12px" class="panel">
          <h4 style="margin:0;color:var(--accent)">Quick actions</h4>
          <div style="margin-top:8px">
            <button id="downloadTxt" style="width:100%;padding:10px;border-radius:8px;background:#fff;border:1px solid #e6ddd2;cursor:pointer">Download plan as .txt</button>
            <a href="{{PRIMARY_CTA_URL}}" class="btn" style="display:block;text-align:center;margin-top:10px">{{PRIMARY_CTA_LABEL}}</a>
          </div>
        </div>
      </aside>
    </div>
  </main>

  <script>
    // Planner builder
    (function(){
      const build = document.getElementById('buildPlan');
      const copyBtn = document.getElementById('copyPlan');
      const planOut = document.getElementById('planOut');
      const previewBtn = document.getElementById('previewBtn');
      const result = document.getElementById('result');
      const submitBtn = document.getElementById('submitBtn');
      const downloadBtn = document.getElementById('downloadTxt');

      function composePlan(){
        const name = document.getElementById('custName').value || '[Name]';
        const intent = document.getElementById('p-intent').value;
        const duration = document.getElementById('p-duration').value;
        const tone = document.getElementById('p-tone').value;
        const env = document.getElementById('p-env').value;
        const type = document.getElementById('type').value;
        const date = document.getElementById('date').value || '[date]';
        const notes = document.getElementById('notes').value || '';

        const lines = [];
        lines.push(`Plan for: ${name}`);
        lines.push(`Session type: ${type}`);
        lines.push(`Preferred date: ${date}`);
        lines.push(`Intention: ${intent}`);
        lines.push(`Duration: ${duration} minutes`);
        lines.push(`Sound texture: ${tone}`);
        lines.push(`Ambience: ${env}`);
        lines.push('Structure:');
        lines.push(` • Gentle arrival (5-8 minutes)`);
        lines.push(` • ${Math.max(10, Math.round(duration*0.6))} minutes layered sound work`);
        lines.push(' • Slow resolution and short silence to close');
        if(notes) lines.push(`Notes: ${notes}`);
        lines.push('Packing suggestions: Cushion, light blanket, water, optional earplugs');

        return lines.join('\n');
      }

      build.addEventListener('click',function(){ planOut.textContent = composePlan(); });
      copyBtn.addEventListener('click',function(){
        navigator.clipboard && navigator.clipboard.writeText(planOut.textContent).then(()=>{
          copyBtn.textContent='Copied'; setTimeout(()=>copyBtn.textContent='Copy',1200);
        })
      });

      previewBtn.addEventListener('click',function(){ result.textContent = composePlan(); window.scrollTo({top:0,behavior:'smooth'}); });

      submitBtn.addEventListener('click',function(){
        // Fake submission flow
        const plan = composePlan();
        alert('Booking request created. You will receive a confirmation email shortly.');
        // In a real app we'd POST to server. Here we just show the plan.
        result.textContent = 'REQUEST SENT:\n\n' + plan;
      });

      downloadBtn.addEventListener('click',function(){
        const blob = new Blob([composePlan()],{type:'text/plain'});
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a'); a.href=url; a.download='session-plan.txt'; document.body.appendChild(a); a.click(); a.remove(); URL.revokeObjectURL(url);
      });

      // Seat grid + packing list
      const seatGrid = document.getElementById('seatGrid');
      const packingBox = document.getElementById('packingBox');
      const seats=20; // 4x5
      for(let i=1;i<=seats;i++){
        const s = document.createElement('div'); s.className='seat'; s.textContent=i; s.dataset.id=i;
        s.addEventListener('click',()=>{
          document.querySelectorAll('.seat').forEach(x=>x.classList.remove('selected'));
          s.classList.add('selected');
          showPacking(i);
        });
        seatGrid.appendChild(s);
      }
      function showPacking(n){
        const items=['Cushion','Light blanket','Water bottle'];
        if(n<=5) items.push('Earplugs (optional)');
        if(n%2===0) items.push('Small towel');
        if(n>15) items.push('Extra lumbar support');
        packingBox.textContent = items.join('\n');
      }
      // Preselect middle seat
      document.querySelectorAll('.seat')[9].click();

    })();
  </script>
